"169 :   private Node trySimplifyUnusedResult(Node n, boolean removeUnused) {
170 :     Node result = n;
171 : 
172 :     // Simplify the results of conditional expressions
173 :     switch (n.getType()) {
174 :       case Token.HOOK:
175 :         Node trueNode = trySimplifyUnusedResult(n.getFirstChild().getNext());
176 :         Node falseNode = trySimplifyUnusedResult(n.getLastChild());
177 :         // If one or more of the conditional children were removed,
178 :         // transform the HOOK to an equivalent operation:
179 :         //    x() ? foo() : 1 --> x() && foo()
180 :         //    x() ? 1 : foo() --> x() || foo()
181 :         //    x() ? 1 : 1 --> x()
182 :         //    x ? 1 : 1 --> null
183 :         if (trueNode == null && falseNode != null) {
184 :           n.setType(Token.OR);
185 :           Preconditions.checkState(n.getChildCount() == 2);
186 :         } else if (trueNode != null && falseNode == null) {
187 :           n.setType(Token.AND);
188 :           Preconditions.checkState(n.getChildCount() == 2);
189 :         } else if (trueNode == null && falseNode == null) {
190 :           result = trySimplifyUnusedResult(n.getFirstChild());
191 :         } else {
192 :           // The structure didn't change.
193 :           result = n;
194 :         }
195 :         break;
196 :       case Token.AND:
197 :       case Token.OR:
198 :         // Try to remove the second operand from a AND or OR operations:
199 :         //    x() || f --> x()
200 :         //    x() && f --> x()
201 :         Node conditionalResultNode = trySimplifyUnusedResult(
202 :             n.getLastChild());
203 :         if (conditionalResultNode == null) {
204 :           Preconditions.checkState(n.hasOneChild());
205 :           // The conditionally executed code was removed, so
206 :           // replace the AND/OR with its LHS or remove it if it isn't useful.
207 :           result = trySimplifyUnusedResult(n.getFirstChild());
208 :         }
209 :         break;
210 :       case Token.FUNCTION:
211 :         // A function expression isn't useful if it isn't used, remove it and
212 :         // don't bother to look at its children.
213 :         result = null;
214 :         break;
215 :       case Token.COMMA:
216 :         // We rewrite other operations as COMMA expressions (which will later
217 :         // get split into individual EXPR_RESULT statement, if possible), so
218 :         // we special case COMMA (we don't want to rewrite COMMAs as new COMMAs
219 :         // nodes.
220 :         Node left = trySimplifyUnusedResult(n.getFirstChild());
221 :         Node right = trySimplifyUnusedResult(n.getLastChild());
222 :         if (left == null && right == null) {
223 :           result = null;
224 :         } else if (left == null) {
225 :           result = right;
226 :         } else if (right == null){
227 :           result = left;
228 :         } else {
229 :           // The structure didn't change.
230 :           result = n;
231 :         }
232 :         break;
233 :       default:
234 :         if (!NodeUtil.nodeTypeMayHaveSideEffects(n)) {
235 :           // This is the meat of this function. The node itself doesn't generate
236 :           // any side-effects but preserve any side-effects in the children.
237 :           Node resultList = null;
238 :           for (Node next, c = n.getFirstChild(); c != null; c = next) {
239 :             next = c.getNext();
240 :             c = trySimplifyUnusedResult(c);
241 :             if (c != null) {
242 :               c.detachFromParent();
243 :               if (resultList == null)  {
244 :                 // The first side-effect can be used stand-alone.
245 :                 resultList = c;
246 :               } else {
247 :                 // Leave the side-effects in-place, simplifying it to a COMMA
248 :                 // expression.
249 :                 resultList = new Node(Token.COMMA, resultList, c)
250 :                     .copyInformationFrom(c);
251 :               }
252 :             }
253 :           }
254 :           result = resultList;
255 :         }
256 :     }
257 : 
258 :     // Fix up the AST, replace or remove the an unused node (if requested).
259 :     if (n != result) {
260 :       Node parent = n.getParent();
261 :       if (result == null) {
262 :         if (removeUnused) {
263 :           parent.removeChild(n);
264 :         } else {
265 :           result = new Node(Token.EMPTY).copyInformationFrom(n);
266 :           parent.replaceChild(n, result);
267 :         }
268 :       } else {
269 :         // A new COMMA expression may not have an existing parent.
270 :         if (result.getParent() != null) {
271 :           result.detachFromParent();
272 :         }
273 :         n.getParent().replaceChild(n, result);
274 :       }
275 :       reportCodeChange();
276 :     }
277 : 
278 :     return result;
279 :   }"

