729 :     // Rather than id which ops may have side effects, id the ones
730 :     // that we know to be safe
731 :     switch (n.getType()) {
732 :       // other side-effect free statements and expressions
733 :       case Token.AND:
734 :       case Token.BLOCK:
735 :       case Token.EXPR_RESULT:
736 :       case Token.HOOK:
737 :       case Token.IF:
738 :       case Token.IN:
739 :       case Token.LP:
740 :       case Token.NUMBER:
741 :       case Token.OR:
742 :       case Token.THIS:
743 :       case Token.TRUE:
744 :       case Token.FALSE:
745 :       case Token.NULL:
746 :       case Token.STRING:
747 :       case Token.SWITCH:
748 :       case Token.TRY:
749 :       case Token.EMPTY:
750 :         break;
751 : 
752 :       // Throws are by definition side effects
753 :       case Token.THROW:
754 :         return true;
755 : 
756 :       case Token.OBJECTLIT:
757 :         if (checkForNewObjects) {
758 :           return true;
759 :         }
760 :         for (Node c = n.getFirstChild(); c != null; c = c.getNext()) {
761 :           if (checkForStateChangeHelper(
762 :                   c.getFirstChild(), checkForNewObjects, compiler)) {
763 :             return true;
764 :           }
765 :         }
766 :         return false;
767 : 
768 :       case Token.ARRAYLIT:
769 :       case Token.REGEXP:
770 :         if (checkForNewObjects) {
771 :           return true;
772 :         }
773 :         break;
