782 :       case Token.FUNCTION:
783 :         // Function expressions don't have side-effects, but function
784 :         // declarations change the namespace. Either way, we don't need to
785 :         // check the children, since they aren't executed at declaration time.
786 :         return checkForNewObjects || !isFunctionExpression(n);
